  if((m=/^lmt-([a-z]+)$/.exec(id))){var mn2=m[1];try{mn2=modeName(m[1])}catch(e){}return {id:id,ty:'title',n:mn2+' master',r:'L',ex:1,how:'Finish '+mn2+' level 5'}}
