 function dev(){var d=null;try{d=localStorage.getItem('critical_act_dev');if(!d){d=Math.random().toString(36).slice(2,10);localStorage.setItem('critical_act_dev',d)}}catch(e){}return d||'dev'}
 function bump(track,i,n){try{var o=rdk('critical_act',null);if(!o||!o.d)o={v:1,d:{}};var me=o.d[dev()]=o.d[dev()]||{},day=me[today()]=me[today()]||{},a=day[track]=day[track]||[0,0,0];while(a.length<=i)a.push(0);a[i]+=n;wrk('critical_act',o);actC=null;try{SYNC.mark()}catch(_){}}catch(e){}}
 var actC=null;function actObj(){if(!actC||Date.now()-actC.t>3000)actC={t:Date.now(),o:rdk('critical_act',{})};return actC.o}
